def check_password(s, n):
    if n < 4: return 0
    if s[0].isdigit(): return 0
    has_digit = False
    has_upper = False
    for char in s:
        if char == ' ' or char == '/':
            return 0
        if char.isdigit():
            has_digit = True
        if char.isupper():
            has_upper = True
    return 1 if (has_digit and has_upper) else 0
```

