def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
L, R = int(input()), int(input())
primes = [x for x in range(L, R + 1) if is_prime(x)]
print(", ".join(map(str, primes)) if primes else "No primes found")
